effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec2 q = uv - vec2(0.5);
q.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
float d = length(q);
float outer = clamp(amount, 0.0, 1.0);
float inner = outer * (1.0 - clamp(feather, 0.05, 1.0));
float m = 1.0 - smoothstep(inner, outer, d);
vec3 outRgb = src.rgb * mix(1.0, m, step(0.001, outer));
float g = fract(sin(dot(floor(uv * vec2(480.0, 270.0)) + seed, vec2(12.9898, 78.233))) * 43758.5453);
outRgb += (g - 0.5) * clamp(grain, 0.0, 0.3);
gl_FragColor = vec4(clamp(outRgb, vec3(0.0), vec3(1.0)), src.a);
}
